-- MY GYM London - 101 more exercises: TRX (25), resistance band (30) and bodyweight for home training (46)
-- Each how-to starts with the level: Beginner, Intermediate or Advanced.
-- Paste into Supabase Dashboard -> SQL Editor -> Run (safe to re-run: skips any name already in the library, any capitals).
with new_rows(name, muscle_group, equipment, how_to, sort) as (values
-- TRX (25)
('TRX high row','Back','TRX','Beginner. Hands at chest height, lean back and pull the elbows out and back to row the chest up to the handles.',364),
('TRX single-arm row','Back','TRX','Intermediate. Hold both handles in one hand, lean back and row, keeping the hips square.',365),
('TRX Y fly','Back','TRX','Intermediate. Lean back with straight arms, raise the arms overhead in a Y shape, then lower slowly.',366),
('TRX face pull','Shoulders','TRX','Beginner. Lean back, pull the handles towards the face with the elbows high and apart.',367),
('TRX archer row','Back','TRX','Advanced. Wide handles, row to one side while the other arm stays straight, then alternate.',368),
('TRX chest fly','Chest','TRX','Intermediate. Lean forward with straight arms, open the arms wide, then bring the hands together.',369),
('TRX decline push-up','Chest','TRX','Advanced. Feet in the straps, hands on the floor, lower the chest and press back up.',370),
('TRX atomic push-up','Chest','TRX','Advanced. Feet in the straps, do a push-up, then pull the knees towards the chest.',371),
('TRX T fly','Shoulders','TRX','Intermediate. Lean back with straight arms, open the arms out to a T, then return slowly.',372),
('TRX triceps extension','Arms','TRX','Intermediate. Lean forward with hands at head height, bend the elbows to lower the head, then extend.',373),
('TRX lunge','Legs','TRX','Beginner. Hold the handles for balance, step back into a lunge and push back up.',374),
('TRX reverse lunge','Legs','TRX','Intermediate. Back foot in a strap, lower the back knee towards the floor, then stand.',375),
('TRX Bulgarian split squat','Legs','TRX','Intermediate. Rear foot in a strap, lower the back knee and push through the front heel.',376),
('TRX single-leg squat','Legs','TRX','Advanced. Hold the handles, sit back on one leg with the other leg out, stand using the straps as little as you can.',377),
('TRX hamstring curl','Legs','TRX','Intermediate. Heels in the straps, hips lifted, curl the heels towards the glutes and extend.',378),
('TRX jump squat','Legs','TRX','Advanced. Hold the handles lightly, squat and jump up, landing softly.',379),
('TRX hip hinge','Lower back','TRX','Beginner. Hold the handles, push the hips back with a flat back and stand tall using the straps for support.',380),
('TRX plank','Core','TRX','Beginner. Forearms on the floor, feet in the straps, hold a straight line from head to heels.',381),
('TRX mountain climber','Core','TRX','Intermediate. Feet in the straps in a plank, drive one knee then the other towards the chest.',382),
('TRX body saw','Core','TRX','Advanced. Forearms on the floor, feet in the straps, rock the body back and forward from the shoulders.',383),
