('TRX oblique crunch','Core','TRX','Intermediate. Feet in the straps, draw the knees towards one elbow, then the other.',385),
('TRX side plank','Core','TRX','Intermediate. Feet in the straps on their side, lift the hips and hold.',386),
('TRX burpee','Full body','TRX','Advanced. Feet in the straps, push-up, pull the knees in, then stand and repeat.',387),
('TRX hip bridge','Glutes','TRX','Beginner. Lie on your back with heels in the straps, lift the hips and squeeze the glutes.',388),
-- Resistance band (30)
('Band chest press','Chest','Resistance band','Beginner. Band behind the back, press the hands forward until the arms are straight, return slowly.',389),
('Band chest fly','Chest','Resistance band','Intermediate. Band behind the back, arms wide, bring the hands together in front of the chest.',390),
('Band push-up','Chest','Resistance band','Advanced. Band across the upper back and under the hands, do a push-up against the extra resistance.',391),
('Band pull-apart','Back','Resistance band','Beginner. Hold the band at chest height, pull it apart until the arms are out to the sides.',392),
('Band lat pulldown','Back','Resistance band','Beginner. Band anchored overhead, pull the hands down to the chest with the elbows down and back.',393),
('Band seated row','Back','Resistance band','Beginner. Seated with the band around the feet, pull the hands to the stomach squeezing the shoulder blades.',394),
('Band single-arm row','Back','Resistance band','Intermediate. Band anchored in front, row one hand to the hip keeping the torso still.',395),
('Band straight-arm pulldown','Back','Resistance band','Intermediate. Band anchored overhead, keep the arms straight and press the hands down to the thighs.',396),
('Band reverse fly','Back','Resistance band','Beginner. Hold the band in front, arms straight, pull it apart to the sides squeezing the upper back.',397),
('Band shoulder press','Shoulders','Resistance band','Beginner. Stand on the band, press the hands from the shoulders to overhead, lower slowly.',398),
('Band lateral raise','Shoulders','Resistance band','Beginner. Stand on the band, raise the arms out to the sides to shoulder height, lower slowly.',399),
('Band face pull','Shoulders','Resistance band','Beginner. Band anchored at face height, pull the hands to the face with the elbows high.',400),
('Band front raise','Shoulders','Resistance band','Beginner. Stand on the band, raise the arms in front to shoulder height, lower slowly.',401),
('Band external rotation','Shoulders','Resistance band','Beginner. Elbow at the side bent to 90 degrees, rotate the forearm out against the band and return.',402),
('Band biceps curl','Arms','Resistance band','Beginner. Stand on the band, curl the hands to the shoulders with the elbows pinned, lower slowly.',403),
