('Elevated pike push-up','Shoulders','Bodyweight','Advanced. Feet on a bench, hips high, lower the head towards the floor and press up.',425),
('Handstand hold','Shoulders','Bodyweight','Advanced. Kick up with your back to a wall, arms straight, hold with the body in a line.',426),
('Wall walk','Shoulders','Bodyweight','Advanced. From a plank with feet at the wall, walk the feet up and the hands in, then walk back down.',427),
('Arm circles','Shoulders','Bodyweight','Beginner. Arms out to the sides, make small circles, then bigger ones, forwards then backwards.',428),
('Inverted biceps curl','Arms','Bodyweight','Intermediate. Hang under a sturdy bar with palms facing you, curl the body up by bending the elbows.',429),
('Feet-elevated bench dip','Arms','Bodyweight','Advanced. Hands on a bench and feet on another, lower by bending the elbows and press up.',430),
('Prone Y-T-W raise','Back','Bodyweight','Beginner. Lie face down, lift the arms into a Y, then a T, then a W, squeezing the shoulder blades.',431),
('Scapular push-up','Back','Bodyweight','Beginner. In a plank with straight arms, let the chest sink between the shoulder blades, then push the floor away.',432),
('Table row','Back','Bodyweight','Intermediate. Lie under a sturdy table, grip the edge and pull the chest up to it.',433),
('Negative pull-up','Back','Pull-up bar','Intermediate. Jump or step up to the top of a pull-up and lower yourself as slowly as you can.',434),
('Archer pull-up','Back','Pull-up bar','Advanced. Wide grip, pull up towards one hand while the other arm stays straight, then alternate.',435),
('Split squat','Legs','Bodyweight','Beginner. Staggered stance, lower the back knee towards the floor and push through the front heel.',436),
('Forward lunge','Legs','Bodyweight','Beginner. Step forward, lower the back knee towards the floor, push back to standing.',437),
('Step-up','Legs','Bodyweight','Beginner. Step onto a sturdy step or chair with one foot, drive up and lower slowly.',438),
('Tempo squat','Legs','Bodyweight','Intermediate. Lower for three seconds, pause at the bottom, then stand up in one second.',439),
('Skater squat','Legs','Bodyweight','Intermediate. Balance on one leg and lower the other knee behind you towards the floor, then stand.',440),
('Rear-foot elevated split squat','Legs','Bodyweight','Intermediate. Back foot on a bench, lower the back knee and push through the front heel.',441),
('Bodyweight calf raise','Legs','Bodyweight','Beginner. Rise onto the balls of both feet, pause at the top, lower slowly.',442),
('Hamstring walkout','Legs','Bodyweight','Intermediate. Lie in a glute bridge, walk the heels out until the legs are nearly straight, then walk back.',443),
('Shrimp squat','Legs','Bodyweight','Advanced. Hold one foot behind you, lower the back knee to the floor on one leg, then stand.',444),
('Reverse Nordic','Legs','Bodyweight','Advanced. Kneeling with the feet anchored, lean back from the knees with a straight body, then return.',445),
('Single-leg glute bridge','Glutes','Bodyweight','Intermediate. Lie on your back with one leg extended, lift the hips on the other leg and squeeze.',446),
('Glute bridge march','Glutes','Bodyweight','Intermediate. In a glute bridge, lift one foot then the other without letting the hips drop.',447),
('Feet-elevated glute bridge','Glutes','Bodyweight','Advanced. Heels on a bench, lift the hips and squeeze the glutes at the top.',448),
('Bodyweight hip thrust','Glutes','Bodyweight','Intermediate. Upper back on a bench, drive the hips up and squeeze at the top.',449),
('Plank jack','Core','Bodyweight','Intermediate. In a plank, jump the feet apart and together while keeping the hips steady.',450),
('Side plank leg lift','Core','Bodyweight','Intermediate. In a side plank, raise the top leg, lower slowly, and repeat before switching sides.',451),
('Hollow rock','Core','Bodyweight','Intermediate. In a hollow body hold, rock gently back and forth keeping the shape.',452),
('Boat hold','Core','Bodyweight','Beginner. Sit leaning back with the legs raised and the chest tall, and hold.',453),
('Elbow-to-knee plank','Core','Bodyweight','Intermediate. In a high plank, bring one knee to the same elbow, return, and alternate.',454),
('Lying windshield wiper','Core','Bodyweight','Advanced. Lie on your back with straight legs up, lower them to one side, then the other, without touching the floor.',455),
('Inchworm','Core','Bodyweight','Beginner. Stand, fold forward, walk the hands out to a plank, then walk them back and stand.',456),
('Crab toe touch','Core','Bodyweight','Intermediate. In a reverse tabletop, lift the opposite hand and foot to touch, then alternate.',457),
('Child''s pose','Lower back','Bodyweight','Beginner. Kneel, sit the hips back towards the heels and reach the arms forward, breathing slowly.',458),
('Lying knee drops','Lower back','Bodyweight','Beginner. Lie on your back with knees bent, lower both knees to one side, then the other, slowly.',459),
('Squat thrust','Full body','Bodyweight','Intermediate. Hands on the floor, jump the feet back to a plank, jump them in, then stand.',460),
('Crab walk','Full body','Bodyweight','Beginner. In a reverse tabletop, walk forwards and backwards on the hands and feet.',461),
('Tuck jump','Full body','Bodyweight','Advanced. Jump up and pull the knees towards the chest, land softly with bent knees.',462),
('Burpee with push-up','Full body','Bodyweight','Advanced. Drop to the floor, do a push-up, jump the feet in and jump up.',463),
('Inchworm push-up','Full body','Bodyweight','Intermediate. Walk the hands out to a plank, do a push-up, walk back and stand.',464)
)
insert into public.exercises (name, muscle_group, equipment, how_to, sort)
select n.name, n.muscle_group, n.equipment, n.how_to, n.sort
from new_rows n
where not exists (select 1 from public.exercises e where lower(e.name) = lower(n.name));
